create table if not exists inventory_locations (id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,name text not null,code text not null,location_type text not null default 'storage' check(location_type in ('storage','bar','kitchen','transit','quarantine')),active boolean not null default true,created_at timestamptz not null default now(),unique(business_id,code));
create table if not exists inventory_batches (id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,ingredient_id uuid not null references ingredients(id) on delete cascade,location_id uuid not null references inventory_locations(id) on delete restrict,batch_code text not null,received_at timestamptz not null default now(),expiry_at timestamptz,quantity numeric(24,8) not null default 0 check(quantity>=0),unit text not null,cost_minor bigint not null default 0 check(cost_minor>=0),status text not null default 'available' check(status in ('available','quarantine','expired','depleted')),created_at timestamptz not null default now(),unique(business_id,ingredient_id,location_id,batch_code));
create table if not exists inventory_transfers (id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,source_location_id uuid not null references inventory_locations(id),destination_location_id uuid not null references inventory_locations(id),status text not null default 'draft' check(status in ('draft','approved','in_transit','received','cancelled')),requested_by uuid references auth.users(id),approved_by uuid references auth.users(id),requested_at timestamptz not null default now(),approved_at timestamptz,received_at timestamptz,created_at timestamptz not null default now(),check(source_location_id<>destination_location_id));
create table if not exists inventory_transfer_lines (id uuid primary key default gen_random_uuid(),transfer_id uuid not null references inventory_transfers(id) on delete cascade,business_id uuid not null references businesses(id) on delete cascade,ingredient_id uuid not null references ingredients(id),batch_id uuid references inventory_batches(id),quantity numeric(24,8) not null check(quantity>0),unit text not null,created_at timestamptz not null default now());
create index if not exists idx_v19_batches_fefo on inventory_batches(business_id,ingredient_id,location_id,status,expiry_at,received_at);
create index if not exists idx_v19_transfers_business on inventory_transfers(business_id,status,requested_at desc);
create index if not exists idx_v19_transfer_lines on inventory_transfer_lines(business_id,transfer_id,ingredient_id);
alter table inventory_locations enable row level security;
alter table inventory_batches enable row level security;
alter table inventory_transfers enable row level security;
alter table inventory_transfer_lines enable row level security;
create policy v19_locations_select on inventory_locations for select using(is_member(business_id));
create policy v19_locations_manage on inventory_locations for all using(has_role(business_id,ARRAY['owner','manager']::member_role[])) with check(has_role(business_id,ARRAY['owner','manager']::member_role[]));
create policy v19_batches_select on inventory_batches for select using(is_member(business_id));
create policy v19_batches_manage on inventory_batches for all using(has_role(business_id,ARRAY['owner','manager']::member_role[])) with check(has_role(business_id,ARRAY['owner','manager']::member_role[]));
create policy v19_transfers_select on inventory_transfers for select using(is_member(business_id));
create policy v19_transfers_manage on inventory_transfers for all using(has_role(business_id,ARRAY['owner','manager']::member_role[])) with check(has_role(business_id,ARRAY['owner','manager']::member_role[]));
create policy v19_transfer_lines_select on inventory_transfer_lines for select using(is_member(business_id));
create policy v19_transfer_lines_manage on inventory_transfer_lines for all using(has_role(business_id,ARRAY['owner','manager']::member_role[])) with check(has_role(business_id,ARRAY['owner','manager']::member_role[]));
create or replace function public.v19_fefo_batch_candidates(p_business_id uuid,p_ingredient_id uuid,p_location_id uuid,p_required_quantity numeric) returns table(batch_id uuid,batch_code text,available_quantity numeric,expiry_at timestamptz,received_at timestamptz) language sql security definer set search_path=public as $$ select b.id,b.batch_code,b.quantity,b.expiry_at,b.received_at from inventory_batches b where b.business_id=p_business_id and b.ingredient_id=p_ingredient_id and b.location_id=p_location_id and b.status='available' and b.quantity>0 and b.quantity>=p_required_quantity order by (b.expiry_at is null),b.expiry_at,b.received_at,b.id $$;
revoke all on function public.v19_fefo_batch_candidates(uuid,uuid,uuid,numeric) from public,anon,authenticated;
grant execute on function public.v19_fefo_batch_candidates(uuid,uuid,uuid,numeric) to authenticated;